// Durable bot outbox. The cron capability is server-only and never appears in browser responses.
async function notificationSchema(db){
 await db.prepare('CREATE TABLE IF NOT EXISTS app_notification_control (id INTEGER PRIMARY KEY CHECK(id=1), cron_key TEXT NOT NULL, last_tick_at INTEGER, last_result TEXT)').run();
 const bytes=crypto.getRandomValues(new Uint8Array(32)),key=Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');
 await db.prepare('INSERT OR IGNORE INTO app_notification_control(id,cron_key) VALUES(1,?)').bind(key).run();
 await db.prepare("CREATE TABLE IF NOT EXISTS app_notification_jobs (id TEXT PRIMARY KEY, kind TEXT NOT NULL, record_id TEXT NOT NULL, recipient TEXT NOT NULL, due_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, retry_at INTEGER NOT NULL DEFAULT 0, lease_token TEXT, lease_until INTEGER, sent_at INTEGER, message_id INTEGER, error TEXT)").run();
 await db.prepare('CREATE INDEX IF NOT EXISTS app_notification_due ON app_notification_jobs(status,retry_at,due_at)').run();
}
async function notificationState(db){const row=await db.prepare('SELECT data FROM site_state WHERE id=1').first();return row?JSON.parse(row.data):null}
function notificationRecord(state,job,now){
 const records=job.kind==='uah'?(state?.uahTopups||[]):(state?.simulationBookings||[]),record=records.find(entry=>entry.id===job.record_id);
 if(job.kind==='uah')return record?.notifyOwner&&record.st==='new'&&record.expiresAt>now?record:null;
 return record?.simulation===true&&record.status==='booked'&&record.at>now&&record.at-300000<=now&&!state.users[record.userId]?.banned?record:null;
}
async function processNotificationJobs(env,origin,now=Date.now()){
 if(env.MIGRATION_READ_ONLY==='true')throw Error('Maintenance in progress');if(!env.DB)throw Error('Notification database unavailable');if(!env.TELEGRAM_BOT_TOKEN)throw Error('Telegram bot is not configured');
 const db=env.DB;await notificationSchema(db);const state=await notificationState(db),result={sent:0,failed:0,skipped:0};
 if(!state)return result;
 const add=async(id,kind,record,recipient,due,expires)=>db.prepare('INSERT OR IGNORE INTO app_notification_jobs(id,kind,record_id,recipient,due_at,expires_at) VALUES(?,?,?,?,?,?)').bind(id,kind,record.id,String(recipient),due,expires).run();
 for(const record of state.uahTopups||[])if(record.notifyOwner&&record.st==='new'&&record.expiresAt>now)await add('uah:'+record.id,'uah',record,1116312381,record.ts,record.expiresAt);
 for(const record of state.simulationBookings||[])if(record.simulation===true&&record.status==='booked'&&record.at-300000<=now&&record.at>now&&/^tg:[1-9][0-9]*$/.test(record.userId||''))await add('booking:'+record.id,'booking',record,record.userId.slice(3),record.at-300000,record.at);
 const due=await db.prepare("SELECT * FROM app_notification_jobs WHERE due_at<=? AND expires_at>? AND attempts<8 AND ((status IN ('pending','failed') AND retry_at<=?) OR (status='sending' AND lease_until<=?)) ORDER BY due_at LIMIT 50").bind(now,now,now,now).all();
 for(const job of due.results){
  const lease=crypto.randomUUID(),claimed=await db.prepare("UPDATE app_notification_jobs SET status='sending',lease_token=?,lease_until=?,attempts=attempts+1 WHERE id=? AND ((status IN ('pending','failed') AND retry_at<=?) OR (status='sending' AND lease_until<=?))").bind(lease,now+120000,job.id,now,now).run();if(!claimed.meta.changes)continue;
  const latest=await notificationState(db),record=notificationRecord(latest,job,now);
  if(!record){await db.prepare("UPDATE app_notification_jobs SET status='skipped',lease_token=NULL,lease_until=NULL WHERE id=? AND lease_token=?").bind(job.id,lease).run();result.skipped++;continue}
  const safeOrigin=new URL(origin).origin;let text;
  if(job.kind==='uah'){
   const user=latest.users[record.userId];text='📥 Новая заявка на пополнение гривнами №'+record.number+'\nИгрок: '+record.user+(user?.telegramUsername?' (@'+user.telegramUsername+')':'')+'\nНик в заявке: '+record.nick+'\nСумма: '+record.amount+' грн\nК начислению: '+record.total+' BU\n\nОткройте раздел «Пополнения → Гривны» в админке. Карта показывается только по кнопке «Показать карту».';
  }else{
   const minutes=Math.max(1,Math.ceil((record.at-now)/60000));text='⏰ Внутренняя запись BrainUp скоро начнётся\n\nДо начала: '+minutes+' мин.\nДата: '+record.date+'\nОкно: '+record.time+'–'+new Date(record.at+300000).toLocaleTimeString('ru-RU',{timeZone:'Europe/Kyiv',hour:'2-digit',minute:'2-digit'})+' (Киев)\nНик: '+record.nick+'\n\nЗайдите в BrainUp заранее и откройте раздел записей. Передача игровых предметов не предусмотрена.';
  }
  try{
   const response=await fetch('https://api.telegram.org/bot'+env.TELEGRAM_BOT_TOKEN+'/sendMessage',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({chat_id:job.recipient,text:text.slice(0,4096),reply_markup:{inline_keyboard:[[{text:job.kind==='uah'?'Открыть админку':'Открыть BrainUp',web_app:{url:safeOrigin+(job.kind==='uah'?'/?screen=admin':'/')}}]]}}),signal:AbortSignal.timeout(8000)}),data=await response.json();
   if(!response.ok||!data.ok)throw Error(data.error_code===403?'Получателю нужно открыть бота и разрешить сообщения':'Telegram временно не доставил сообщение');
   await db.prepare("UPDATE app_notification_jobs SET status='sent',sent_at=?,message_id=?,error=NULL,lease_token=NULL,lease_until=NULL WHERE id=? AND lease_token=?").bind(now,data.result?.message_id||null,job.id,lease).run();result.sent++;
  }catch(error){await db.prepare("UPDATE app_notification_jobs SET status='failed',error=?,retry_at=?,lease_token=NULL,lease_until=NULL WHERE id=? AND lease_token=?").bind(String(error.message||'Ошибка отправки').slice(0,200),now+Math.min(60000,15000*(job.attempts+1)),job.id,lease).run();result.failed++;}
 }
 await db.prepare("UPDATE app_notification_jobs SET status='expired' WHERE expires_at<=? AND status IN ('pending','failed','sending')").bind(now).run();
 await db.prepare('UPDATE app_notification_control SET last_tick_at=?,last_result=? WHERE id=1').bind(now,JSON.stringify(result)).run();return result;
}
async function handleNotificationTick(request,env){
 if(request.method!=='POST')return new Response('Method not allowed',{status:405});if(env.MIGRATION_READ_ONLY==='true')return Response.json({ok:false},{status:503});if(!env.DB)return Response.json({ok:false},{status:503});await notificationSchema(env.DB);
 const control=await env.DB.prepare('SELECT cron_key FROM app_notification_control WHERE id=1').first(),provided=request.headers.get('Authorization')?.replace(/^Bearer /,'')||'';
 let difference=provided.length^(control?.cron_key.length||0);for(let i=0;i<(control?.cron_key.length||0);i++)difference|=control.cron_key.charCodeAt(i)^(provided.charCodeAt(i)||0);
 if(difference||!control?.cron_key)return Response.json({ok:false,error:'Unauthorized'},{status:401,headers:{'Cache-Control':'no-store'}});
 try{return Response.json({ok:true,...await processNotificationJobs(env,new URL(request.url).origin)},{headers:{'Cache-Control':'no-store'}})}catch{return Response.json({ok:false,error:'Notification service unavailable'},{status:503})}
}

// Active authenticated feed traffic is a fallback; it is not an unattended scheduler.
var notificationTrafficLastAt=0;
function processNotificationsFromTraffic(env,origin,ctx,now=Date.now()){
 if(!env.DB||!env.TELEGRAM_BOT_TOKEN||env.MIGRATION_READ_ONLY==='true'||now-notificationTrafficLastAt<60000)return null;
 notificationTrafficLastAt=now;const work=processNotificationJobs(env,origin,now).catch(()=>null);if(ctx?.waitUntil)ctx.waitUntil(work);return work;
}

// Partner revenue is a share of settled game margin, never a second fee on deposits.
const PARTNER_GAMES=new Set(['case','upgrade','dice','fuse','fuse-hit','mines-open','mines-cash']);
const partnerCents=value=>Math.round((Number(value)||0)*100);
function activePlayerPartner(s,u,code=u?.bound,allowDisabled=false){
 const p=code&&s.partners[code];return p&&u&&p.userId!==u.id&&(allowDisabled||!p.disabled)?p:null;
}
function partnerPlayerRow(p,u){
 p.list??=[];let row=p.list.find(entry=>entry.k===u.id);
 if(!row){row={k:u.id,name:u.me,vol:0,earned:0,ts:Date.now()};p.list.push(row);p.count=(Number(p.count)||0)+1;}return row;
}
function recordPartnerDeposit(s,u,amount,code=u?.bound){
 const p=activePlayerPartner(s,u,code,amount<0);if(!p)return null;
 const row=partnerPlayerRow(p,u),cents=partnerCents(amount);
 p.vol=Math.max(0,partnerCents(p.vol)+cents)/100;row.vol=Math.max(0,partnerCents(row.vol)+cents)/100;return p.code;
}
function capturePartnerGame(s,id,seed,action,b){
 if(!PARTNER_GAMES.has(action))return null;
 const u=s.users[id],p=activePlayerPartner(s,u),pct=Number(p?.pct);if(!p||!Number.isFinite(pct)||pct<0||pct>100)return null;
 const prices=new Map([...seed.items,...s.config.custom].map(item=>[Number(item.id),partnerCents(withCatalogPrice(item,s.config.itemPrices).price)]));
 const owned=uid=>{const item=u.inv.find(item=>item.uid===Number(uid));return item?prices.get(Number(item.id))||0:0};
 let stake=0;
 if(action==='case'){const c=s.config.cases.find(c=>c.id===Number(b.id));stake=b.free?0:partnerCents((c?.price||0)*Number(b.n||1));}
 else if(action==='upgrade')stake=(Array.isArray(b.ids)?b.ids:[]).reduce((sum,uid)=>sum+owned(uid),0)+partnerCents(b.coins);
 else if(action==='dice')stake=b.bet?.type==='coin'?partnerCents(b.bet.amt):owned(b.bet?.uid);
 else if(action==='fuse')stake=(Array.isArray(b.ids)?b.ids:[]).reduce((sum,uid)=>sum+owned(uid),0);
 else if(action.startsWith('mines-'))stake=partnerCents(u.mine?.stake);
 return {code:p.code,pct,stake,action};
}
function settlePartnerGame(s,id,snapshot,result,now){
 if(!snapshot||snapshot.action.startsWith('mines-')&&!result.end||snapshot.action==='fuse-hit'&&!result.prize)return;
 const u=s.users[id],p=s.partners[snapshot.code];if(!p)return;
 let payout=0;
 if(snapshot.action==='case')payout=result.wins.reduce((sum,win)=>sum+partnerCents(win.w.price),0);
 else if(snapshot.action==='upgrade')payout=result.win?partnerCents(result.target.price):0;
 else if(snapshot.action==='dice'||snapshot.action.startsWith('mines-'))payout=partnerCents(result.paid);
 else if(snapshot.action==='fuse')payout=partnerCents(result.w.price)+partnerCents(result.extra?.w.price);
 else if(snapshot.action==='fuse-hit')payout=partnerCents(result.prize.w.price);
 const margin=snapshot.stake-payout;
 // Symmetric cent rounding keeps positive and negative adjustments balanced.
 const commission=Math.sign(margin)*Math.round(Math.abs(margin)*snapshot.pct/100),row=partnerPlayerRow(p,u);
 p.pending=(partnerCents(p.pending)+commission)/100;row.earned=(partnerCents(row.earned)+commission)/100;
 p.gameStakes=(partnerCents(p.gameStakes)+snapshot.stake)/100;p.gamePayouts=(partnerCents(p.gamePayouts)+payout)/100;p.gameMargin=(partnerCents(p.gameMargin)+margin)/100;
 row.gameStakes=(partnerCents(row.gameStakes)+snapshot.stake)/100;row.gamePayouts=(partnerCents(row.gamePayouts)+payout)/100;
 p.gameLedger=[{id:crypto.randomUUID(),at:now,userId:id,user:u.me,game:snapshot.action,stake:snapshot.stake/100,payout:payout/100,margin:margin/100,pct:snapshot.pct,amount:commission/100},...(p.gameLedger||[])].slice(0,200);
}

const UAH_TOPUP_AMOUNTS=[10,20,50,100,200,500,1000,2000,5000,10000];
const uahAssert=(ok,message)=>{if(!ok)throw Error(message)};
function uahTopupView(record,now=Date.now()){
 const st=['new','ready','checking'].includes(record.st)&&record.expiresAt<=now?'expired':record.st;
 const {card,...safe}=record;return {...safe,st,...(['ready','checking','ok'].includes(st)&&record.shownAt?{card}:{} )};
}
function executeUahTopup(s,id,action,b,now){
 if(!['uah-card-save','uah-topup','uah-show-card','uah-paid','uah-review','uah-cancel'].includes(action))return null;
 const owner=()=>uahAssert(s.owner===id,'Доступ только владельцу');
 if(action==='uah-card-save'){
  owner();const raw=String(b.card??'').trim();uahAssert(/^[\d\s-]*$/.test(raw),'Введите только номер карты');const card=raw.replace(/[\s-]/g,'');uahAssert(card===''||/^\d{16}$/.test(card),'Номер карты должен содержать 16 цифр');
  s.config.uahCard=card;return {configured:!!card};
 }
 const user=s.users[id];uahAssert(user,'Сначала войдите');
 if(action==='uah-topup'){
  uahAssert(!s.config.topupsClosed&&!s.config.topupsUahClosed,'Пополнения гривнами временно закрыты');uahAssert(!!s.config.uahCard,'Пополнение гривнами пока не настроено');
  uahAssert(typeof b.amount==='number'&&Number.isFinite(b.amount)&&b.amount>=1&&b.amount<=1000000&&Math.abs(b.amount*100-Math.round(b.amount*100))<1e-6,'Введите сумму от 1 до 1 000 000 грн, до двух знаков после запятой');
  uahAssert(!(s.uahTopups||[]).some(r=>r.userId===id&&['new','ready','checking'].includes(uahTopupView(r,now).st)),'У вас уже есть активная заявка');
  const nick=String(b.nick||user.me||'Игрок').trim();uahAssert(nick.length>=1&&nick.length<=32&&!/[\u0000-\u001f\u007f]/.test(nick),'Введите ник: до 32 символов');
  const code=String(b.promo||'').trim().toUpperCase();if(code){const partner=s.partners[code];uahAssert(partner&&!partner.disabled&&partner.userId!==id,'Код партнёра не найден');uahAssert(!user.bound||user.bound===code,'Вы уже привязаны к другому партнёру');if(!user.bound){user.bound=code;partner.list??=[];partner.list.push({k:id,name:user.me,vol:0,earned:0,ts:now});partner.count=partner.list.length;}}
  const record={id:crypto.randomUUID(),number:(s.uahTopupNumber||0)+1,userId:id,user:user.me,nick,type:'uah',amount:b.amount,rate:1.25,total:Math.round(Math.round(b.amount*100)*1.25)/100,notifyOwner:true,promo:user.bound||'',st:'new',ts:now,expiresAt:now+1800000};
  s.uahTopupNumber=record.number;(s.uahTopups||=[]).push(record);return {topup:uahTopupView(record,now)};
 }
 const record=(s.uahTopups||[]).find(r=>r.id===b.id);uahAssert(record,'Заявка не найдена');
 if(['uah-show-card','uah-review'].includes(action))owner();else uahAssert(record.userId===id,'Заявка не найдена');
 uahAssert(['new','ready','checking'].includes(uahTopupView(record,now).st),'Заявка уже обработана или истекла');
 if(action==='uah-show-card'){uahAssert(record.st==='new','Карта уже показана');uahAssert(!!s.config.uahCard,'Сначала сохраните номер карты');record.card=s.config.uahCard;record.shownAt=now;record.st='ready';record.expiresAt=now+1800000;}
 else if(action==='uah-paid'){uahAssert(record.st==='ready','Сначала дождитесь реквизитов');record.st='checking';record.paymentClaimedAt=now;record.expiresAt=now+86400000;}
 else if(action==='uah-cancel'){uahAssert(record.st!=='checking','Оплата уже передана на проверку');record.st='no';record.cancelledAt=now;}
 else if(action==='uah-review'){
  uahAssert(['ok','no'].includes(b.status),'Выберите решение');if(b.status==='ok'){uahAssert(record.st==='checking','Сначала дождитесь отметки об оплате');const target=s.users[record.userId];uahAssert(target,'Игрок не найден');target.balance=(Math.round(target.balance*100)+Math.round(record.total*100))/100;recordPartnerDeposit(s,target,record.total,record.promo);}
  record.st=b.status;record.processedAt=now;record.processedBy=id;
 }
 return {topup:uahTopupView(record,now)};
}

const TOPUP_PREFIX = 'topup:';
const BU_CENTS_PER_STAR = 125;

async function applyStarsBalance(db, order, refunded) {
 const userKey = 'tg:' + order.user_id;
 for (let attempt = 0; attempt < 12; attempt++) {
  const row = await db.prepare('SELECT revision, data FROM site_state WHERE id = 1').first();
  const state = row && JSON.parse(row.data);
  const user = state?.users[userKey];
  if (!user) throw Error('Payment account unavailable');
  const entries = state.starsBalanceEntries ??= {};
  const previous = entries[order.id];
  if (previous === 'refunded' || (previous === 'paid' && !refunded)) return;
  const cents = order.stars * (order.bu_rate||135);
  const delta = refunded ? (previous === 'paid' ? -cents : 0) : cents;
  user.balance = (Math.round(user.balance * 100) + delta) / 100;
  const partnerEntries=state.starsPartnerEntries??={};
  if(!refunded){const code=recordPartnerDeposit(state,user,cents/100);if(code)partnerEntries[order.id]={code,amount:cents/100};}
  else if(previous==='paid'&&partnerEntries[order.id]){const entry=partnerEntries[order.id];recordPartnerDeposit(state,user,-entry.amount,entry.code);entry.refunded=true;}
  entries[order.id] = refunded ? 'refunded' : 'paid';
  const result = await db.prepare('UPDATE site_state SET revision = revision + 1, data = ? WHERE id = 1 AND revision = ?')
   .bind(JSON.stringify(state), row.revision).run();
  if (result.meta.changes === 1) return;
 }
 throw Error('Payment balance update must be retried');
}

export async function supportSchema(db){
 await db.prepare("CREATE TABLE IF NOT EXISTS support_payments (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL, stars INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending', invoice_url TEXT, checkout_query TEXT, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, bu_rate INTEGER NOT NULL DEFAULT 135)").run();
 const rateColumn=async()=>{const info=await db.prepare('PRAGMA table_info("support_payments")').all();return info.results.some(column=>column.name==='bu_rate')};
 if(!await rateColumn())try{await db.prepare('ALTER TABLE support_payments ADD COLUMN bu_rate INTEGER NOT NULL DEFAULT 135').run()}catch(error){if(!await rateColumn())throw error;}
 await db.prepare('CREATE TABLE IF NOT EXISTS support_receipts (charge_id TEXT PRIMARY KEY, payment_id TEXT NOT NULL, user_id INTEGER NOT NULL, stars INTEGER NOT NULL, paid_at INTEGER NOT NULL, refunded_at INTEGER)').run();
}
async function supportApi(env,method,body){if(!env.TELEGRAM_BOT_TOKEN)throw Error('Оплата пока недоступна');const response=await fetch('https://api.telegram.org/bot'+env.TELEGRAM_BOT_TOKEN+'/'+method,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(7000)}),data=await response.json();if(!response.ok||!data.ok)throw Error('Telegram не ответил. Повторите позже.');return data.result;}
async function supportAllowed(db,id){const row=await db.prepare('SELECT data FROM site_state WHERE id = 1').first(),state=row?JSON.parse(row.data):null;return !state?.config.topupsClosed&&!state?.config.topupsStarsClosed&&!state?.users['tg:'+id]?.banned;}
export async function handleSupport(request,env,identity){
 const json=(data,status=200)=>Response.json(data,{status,headers:{'Cache-Control':'no-store'}});
 if(!identity?.id?.startsWith('tg:'))return json({ok:false,error:'Откройте оплату в Telegram'},401);
 if(!env.DB||!env.TELEGRAM_BOT_TOKEN||!env.TELEGRAM_WEBHOOK_SECRET)return json({ok:false,error:'Оплата пока недоступна'},503);
 const userId=Number(identity.id.slice(3));if(!Number.isSafeInteger(userId)||userId<=0)return json({ok:false,error:'Некорректный аккаунт'},401);
 await supportSchema(env.DB);const url=new URL(request.url);
 if(request.method==='GET'){
  if(url.searchParams.get('admin')==='1'){
   if(userId!==1116312381)return json({ok:false,error:'Доступ только владельцу'},403);
   const rows=await env.DB.prepare("SELECT json_group_array(json_object('chargeId',charge_id,'paymentId',payment_id,'userId',user_id,'stars',stars,'paidAt',paid_at,'refundedAt',refunded_at)) AS data FROM (SELECT * FROM support_receipts ORDER BY paid_at DESC LIMIT 100)").first();return json({ok:true,payments:JSON.parse(rows?.data||'[]')});
  }
  const id=url.searchParams.get('id'),row=await env.DB.prepare('SELECT * FROM support_payments WHERE id IN (?, ?) AND user_id = ? ORDER BY id DESC LIMIT 1').bind(id,TOPUP_PREFIX+id,userId).first();if(!row)return json({ok:false,error:'Платёж не найден'},404);
  return json({ok:true,id,stars:row.stars,creditedBU:row.status==='paid'&&row.id.startsWith(TOPUP_PREFIX)?row.stars*(row.bu_rate||135)/100:0,status:row.status,invoiceUrl:row.status==='pending'&&row.expires_at>Date.now()?row.invoice_url:null});
 }
 if(request.method!=='POST')return json({ok:false,error:'Method not allowed'},405);
 if(request.headers.get('origin')&&request.headers.get('origin')!==url.origin)return json({ok:false,error:'Недопустимый источник'},403);
 if(!request.headers.get('content-type')?.startsWith('application/json'))return json({ok:false,error:'Ожидается JSON'},415);
 let body;try{const raw=await request.text();if(raw.length>1024)throw Error();body=JSON.parse(raw)}catch{return json({ok:false,error:'Некорректный запрос'},400)}
 if(!/^[a-f0-9-]{36}$/i.test(body.id||'')||!Number.isSafeInteger(body.stars)||body.stars<1||body.stars>10000)return json({ok:false,error:'Укажите целое число от 1 до 10 000 Stars'},400);
 if(!await supportAllowed(env.DB,userId))return json({ok:false,error:'Пополнения временно закрыты'},403);
 const stateRow=await env.DB.prepare('SELECT data FROM site_state WHERE id = 1').first();
 if(!stateRow||!JSON.parse(stateRow.data).users[identity.id])return json({ok:false,error:'Сначала войдите в аккаунт BrainUp'},409);
 const orderId=TOPUP_PREFIX+body.id;
 const now=Date.now();await env.DB.prepare('INSERT OR IGNORE INTO support_payments(id,user_id,stars,created_at,expires_at,bu_rate) VALUES (?,?,?,?,?,?)').bind(orderId,userId,body.stars,now,now+1800000,BU_CENTS_PER_STAR).run();
 const row=await env.DB.prepare('SELECT * FROM support_payments WHERE id = ?').bind(orderId).first();if(row.user_id!==userId||row.stars!==body.stars)return json({ok:false,error:'Платёж не совпадает'},409);
 if(row.status!=='pending'||row.expires_at<=now)return json({ok:false,error:'Создайте новый платёж'},409);
 let invoice=row.invoice_url;
 if(!invoice){try{await supportApi(env,'setWebhook',{url:new URL('/telegram/webhook',request.url).href,secret_token:env.TELEGRAM_WEBHOOK_SECRET,allowed_updates:['message','callback_query','pre_checkout_query']});invoice=await supportApi(env,'createInvoiceLink',{title:'Пополнение BrainUp',description:'На баланс поступит '+row.stars*(row.bu_rate||135)/100+' BU.',payload:'support:'+row.id,currency:'XTR',prices:[{label:'Пополнение BU',amount:row.stars}]});if(typeof invoice!=='string'||!invoice.startsWith('https://t.me/'))throw Error('Некорректный ответ Telegram');await env.DB.prepare('UPDATE support_payments SET invoice_url = ? WHERE id = ?').bind(invoice,row.id).run()}catch(error){return json({ok:false,error:error.message},502)}}
 return json({ok:true,id:body.id,stars:row.stars,invoiceUrl:invoice,status:'pending'});
}
export async function supportTelegramUpdate(update,env,api){
 const query=update.pre_checkout_query,payment=update.message?.successful_payment,refund=update.message?.refunded_payment;
 if(!query&&!payment&&!refund)return false;
 if(!env.DB)throw Error('Payment database unavailable');await supportSchema(env.DB);
 const event=query||payment||refund,payload=event.invoice_payload||'',id=payload.startsWith('support:')?payload.slice(8):'',userId=query?.from?.id||update.message?.from?.id;
 const order=await env.DB.prepare('SELECT * FROM support_payments WHERE id = ?').bind(id).first();
 const valid=order&&userId===order.user_id&&event.currency==='XTR'&&event.total_amount===order.stars;
 if(query){
  let accepted=!!valid&&!!order.invoice_url&&order.expires_at>Date.now()&&await supportAllowed(env.DB,userId);
  if(accepted&&order.status==='pending'){const changed=await env.DB.prepare("UPDATE support_payments SET status='checkout', checkout_query=? WHERE id=? AND status='pending'").bind(query.id,id).run();accepted=changed.meta.changes===1;if(!accepted){const latest=await env.DB.prepare('SELECT * FROM support_payments WHERE id=?').bind(id).first();accepted=latest?.status==='checkout'&&latest.checkout_query===query.id}}
  else if(accepted)accepted=order.status==='checkout'&&order.checkout_query===query.id;
  await api('answerPreCheckoutQuery',{pre_checkout_query_id:query.id,ok:accepted,...(!accepted?{error_message:'Платёж недоступен или уже обработан. Создайте новый счёт в приложении.'}:{})});return true;
 }
 if(!valid||!event.telegram_payment_charge_id)throw Error('Payment does not match an issued invoice');
 if(id.startsWith(TOPUP_PREFIX)&&!['checkout','paid','refunded'].includes(order.status))throw Error('Checkout was not approved');
 const charge=event.telegram_payment_charge_id,now=Date.now(),previous=await env.DB.prepare('SELECT * FROM support_receipts WHERE charge_id=?').bind(charge).first();
 if(previous&&(previous.payment_id!==id||previous.user_id!==userId||previous.stars!==order.stars))throw Error('Payment receipt mismatch');
 await env.DB.prepare('INSERT OR IGNORE INTO support_receipts(charge_id,payment_id,user_id,stars,paid_at,refunded_at) VALUES (?,?,?,?,?,?)').bind(charge,id,userId,order.stars,now,refund?now:null).run();
 if(refund)await env.DB.prepare('UPDATE support_receipts SET refunded_at=? WHERE charge_id=?').bind(now,charge).run();
 const receipt=await env.DB.prepare('SELECT * FROM support_receipts WHERE charge_id=?').bind(charge).first();
 if(id.startsWith(TOPUP_PREFIX))await applyStarsBalance(env.DB,order,!!receipt.refunded_at);
 await env.DB.prepare("UPDATE support_payments SET status=CASE WHEN status='refunded' OR ? THEN 'refunded' ELSE 'paid' END WHERE id=?").bind(receipt.refunded_at?1:0,id).run();
 return true;
}

// Telegram Mini App identity is trusted only after server-side HMAC verification.
export async function telegramIdentity(raw, token, now = Date.now()) {
  if (!token || !raw || raw.length > 16384) throw Error('Telegram не настроен или данные входа отсутствуют');
  const p = new URLSearchParams(raw), seen = new Set();
  for (const [key] of p) { if (seen.has(key)) throw Error('Некорректные данные Telegram'); seen.add(key); }
  const hash = p.get('hash'); p.delete('hash');
  if (!/^[a-f0-9]{64}$/.test(hash || '')) throw Error('Некорректная подпись Telegram');
  const enc = new TextEncoder();
  const key = await crypto.subtle.importKey('raw', enc.encode('WebAppData'), {name:'HMAC', hash:'SHA-256'}, false, ['sign']);
  const secret = await crypto.subtle.sign('HMAC', key, enc.encode(token));
  const signing = await crypto.subtle.importKey('raw', secret, {name:'HMAC',hash:'SHA-256'}, false, ['verify']);
  const check = [...p.entries()].sort(([a],[b])=>a<b?-1:a>b?1:0).map(([k,v])=>k+'='+v).join('\n');
  const valid = await crypto.subtle.verify('HMAC', signing, Uint8Array.from(hash.match(/../g), x=>parseInt(x,16)), enc.encode(check));
  if (!valid) throw Error('Неверная подпись Telegram');
  const date = Number(p.get('auth_date')), age = now/1000-date;
  if (!Number.isFinite(date) || age < -30 || age > 3600) throw Error('Откройте Mini App заново: вход устарел');
  const user = JSON.parse(p.get('user') || 'null');
  if (!Number.isSafeInteger(user?.id) || user.id <= 0) throw Error('Пользователь Telegram отсутствует');
  const photo=typeof user.photo_url==='string'&&user.photo_url.startsWith('https://')?user.photo_url:'';
  const telegramProfile={id:user.id,username:String(user.username||''),first_name:String(user.first_name||''),last_name:String(user.last_name||''),photo_url:photo};
  return {telegramProfile,id:'tg:'+user.id, telegramUsername:String(user.username||'').toLowerCase(), name:[user.first_name,user.last_name].filter(Boolean).join(' ').slice(0,100)||user.username||'Player'};
}
export function buildBotKeyboard(origin,env={}) {
  const supportUrl = 'https://t.me/BrainUpOfficialSupport_bot';
  return {inline_keyboard:[
    [{text:'🚀 Играть',web_app:{url:new URL('/',origin).href}}],
    [{text:'📰 Новости',url:env.TELEGRAM_NEWS_URL||'https://t.me/BrainUp_Official'},{text:'💬 Поддержка',url:supportUrl}],
    [{text:'🎁 Ввести бонус-код',callback_data:'bonus_code'}],
    [{text:'🤝 Партнёрство',web_app:{url:new URL('/?screen=partnership',origin).href}}]
  ]};
}
export async function telegramWebhook(request, env, defaultStartPhoto) {
  if (!env.TELEGRAM_BOT_TOKEN || !env.TELEGRAM_WEBHOOK_SECRET) return new Response('Not configured',{status:503});
  if (request.method !== 'POST' || request.headers.get('X-Telegram-Bot-Api-Secret-Token') !== env.TELEGRAM_WEBHOOK_SECRET) return new Response('Forbidden',{status:403});
  const update=await request.json(),m=update.message,q=update.callback_query,origin=new URL('/',request.url).href;
  const api=async(method,body)=>{const r=await fetch('https://api.telegram.org/bot'+env.TELEGRAM_BOT_TOKEN+'/'+method,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const j=await r.json();if(!r.ok||!j.ok)throw Error('Telegram request failed');return j.result};
  const prompt='🎁 Введите бонус-код ответом на это сообщение:';
  const ask=chat_id=>api('sendMessage',{chat_id,text:prompt,reply_markup:{force_reply:true,input_field_placeholder:'Бонус-код',selective:true}});
  try {
    if(await supportTelegramUpdate(update,env,api))return new Response('OK');
    if(m?.chat?.type==='private'&&/^\/paysupport(?:@\w+)?$/.test(String(m.text||'').trim())){await api('sendMessage',{chat_id:m.chat.id,text:'По вопросам оплаты напишите в поддержку: https://t.me/BrainUpOfficialSupport_bot. Приложите квитанцию Telegram и дату платежа.'});return new Response('OK');}
    const actor=m?.from||q?.from;
    if(actor&&env.DB){const row=await env.DB.prepare('SELECT revision, data FROM site_state WHERE id = 1').first();if(row&&JSON.parse(row.data).users['tg:'+actor.id]?.banned){if(q)await api('answerCallbackQuery',{callback_query_id:q.id,text:'Доступ заблокирован',show_alert:true});else if(m.chat?.type==='private')await api('sendMessage',{chat_id:m.chat.id,text:'Доступ к BrainUp заблокирован.'});return new Response('OK');}}
    if(await browserLoginTelegramUpdate(update,env,api,origin))return new Response('OK');
    if(q?.data==='bonus_code'&&q.message?.chat?.type==='private'&&q.message.chat.id===q.from?.id){
      await api('answerCallbackQuery',{callback_query_id:q.id});await ask(q.from.id);return new Response('OK');
    }
    if(m?.chat?.type!=='private'||!Number.isSafeInteger(m.from?.id))return new Response('OK');
    const text=String(m.text||'').trim();
    if(/^\/start(?:@\w+)?(?:\s|$)/.test(text)){
      let referralNote='';
      const referral=/^\/start(?:@\w+)?\s+ref_([A-Za-z0-9_-]{3,20})$/.exec(text);
      if(referral&&env.DB){
        if(!Number.isSafeInteger(update.update_id))return new Response('Invalid update',{status:400});
        const user=m.from,identity={id:'tg:'+user.id,name:[user.first_name,user.last_name].filter(Boolean).join(' ')||user.username||'Player',telegramUsername:user.username||'',telegramProfile:{id:user.id,username:user.username||'',first_name:user.first_name||'',last_name:user.last_name||'',photo_url:''}};
        const operation=new Request(new URL('/api/action',origin),{method:'POST',headers:{Origin:new URL(origin).origin,'Content-Type':'application/json'},body:JSON.stringify({action:'ref-bind',requestId:'telegram-referral-'+update.update_id,data:{code:referral[1]}})});
        const result=await (await handle(operation,env.DB,identity)).json();
        referralNote=result.ok?'\n\n🤝 Приглашение партнёра сохранено.':/навсегда|привязан/.test(result.error||'')?'\n\nТы уже привязан к партнёру. Привязка сохранена.':'\n\nПриглашение недействительно или недоступно.';
      }
      // Enable callbacks for the new keyboard when an existing user opens the bot.
      await api('setWebhook',{url:new URL('/telegram/webhook',origin).href,secret_token:env.TELEGRAM_WEBHOOK_SECRET,allowed_updates:['message','callback_query','pre_checkout_query']});
      const welcome = '👋 Добро пожаловать в BrainUp!\n\nСобирай брейнротов и играй.\nНажми «🚀 Играть», чтобы открыть приложение.'+referralNote;
      const keyboard = {chat_id:m.chat.id,reply_markup:buildBotKeyboard(origin,env)};
      const photo = env.TELEGRAM_START_PHOTO?.trim() || defaultStartPhoto;
      if (photo) {
        await api('sendPhoto',{...keyboard,photo,caption:welcome});
      } else {
        await api('sendMessage',{...keyboard,text:welcome});
      }
      return new Response('OK');
    }
    const moderation=/^\/(ban|unban)(?:@\w+)?(?:\s+(\S+))?$/i.exec(text);
    if(moderation){
      if(!Number.isSafeInteger(update.update_id))return new Response('Invalid update',{status:400});
      const who=m.from,identity={id:'tg:'+who.id,name:who.first_name||'Player',telegramUsername:who.username||''};
      const operation=new Request(new URL('/api/action',origin),{method:'POST',headers:{'Content-Type':'application/json',Origin:new URL(origin).origin},body:JSON.stringify({action:'admin-ban',requestId:'telegram-ban-'+update.update_id,data:{lookup:moderation[2]||'',banned:moderation[1].toLowerCase()==='ban'}})});
      const response=await handle(operation,env.DB,identity),result=await response.json();
      await api('sendMessage',{chat_id:m.chat.id,text:result.ok?(result.result.banned?'⛔ Игрок заблокирован: ':'✅ Игрок разблокирован: ')+(result.result.username?'@'+result.result.username:result.result.name):'❌ '+(result.error||'Укажите /ban @username или /unban Telegram_ID')});
      return new Response('OK');
    }
    if(/^\/bonus(?:@\w+)?$/.test(text)){await ask(m.chat.id);return new Response('OK');}
    const botId=Number(env.TELEGRAM_BOT_TOKEN.split(':')[0]);
    const trustedReply=m.reply_to_message?.from?.id===botId&&m.reply_to_message?.text===prompt;
    const command=/^\/bonus(?:@\w+)?\s+(.+)$/i.exec(text);
    const code=command?command[1].trim():trustedReply?text:null;
    if(code!==null){
      if(!/^[A-Za-z0-9_-]{3,20}$/.test(code)){await api('sendMessage',{chat_id:m.chat.id,text:'Код должен содержать 3–20 латинских букв, цифр, _ или -.'});return new Response('OK');}
      if(!Number.isSafeInteger(update.update_id))return new Response('Invalid update',{status:400});
      const user=m.from,identity={id:'tg:'+user.id,name:[user.first_name,user.last_name].filter(Boolean).join(' ')||user.username||'Player',telegramUsername:user.username||'',telegramProfile:{id:user.id,username:user.username||'',first_name:user.first_name||'',last_name:user.last_name||'',photo_url:''}};
      const action=new Request(new URL('/api/action',origin),{method:'POST',headers:{'Content-Type':'application/json',Origin:new URL(origin).origin},body:JSON.stringify({action:'promo-redeem',requestId:'telegram-'+update.update_id,data:{code}})});
      const response=await handle(action,env.DB,identity),result=await response.json();
      await api('sendMessage',{chat_id:m.chat.id,text:result.ok?'✅ Бонус-код активирован. Награда доступна в приложении.':'❌ '+(result.error||'Не удалось активировать код'),reply_markup:buildBotKeyboard(origin,env)});
    }
    return new Response('OK');
  }catch{return new Response('Retry',{status:502});}
}

export async function notifyTopupCreated(env,record){
 if(!env.TELEGRAM_BOT_TOKEN)throw Error('Telegram bot is not configured');
 const entries=(record.items||[]).map(x=>x.n+' ×'+x.q),what=record.type==='stars'?'Единицы: '+record.stars:entries.slice(0,30).join('\n')+(entries.length>30?'\n… ещё '+(entries.length-30)+' позиций':'');
 const text=('📥 Заявка на пополнение №'+(record.number||record.id)+'\nИгрок: '+record.user+(record.username?' (@'+record.username+')':'')+'\nНик игрока: '+(record.nick||'не указан')+'\n\n'+what+'\n\nК начислению: '+record.total+' токенов\nОжидание: 10 минут. Решение — в админке BrainUp.').slice(0,4096);
 const response=await fetch('https://api.telegram.org/bot'+env.TELEGRAM_BOT_TOKEN+'/sendMessage',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({chat_id:1116312381,text})}),result=await response.json();if(!response.ok||!result.ok)throw Error('Telegram top-up notification failed');return result.result;
}

export async function notifySimulationTopupCreated(env,record){
 if(record?.simulation!==true||record.free!==true||record.st!=='new')return null;
 if(!env.TELEGRAM_BOT_TOKEN)throw Error('Telegram bot is not configured');
 const entries=(record.items||[]).slice(0,30).map(x=>String(x.n)+' ×'+x.q);
 const what=record.type==='stars'?'Stars: '+record.stars+' (расчёт без оплаты)':entries.join('\n')+((record.items||[]).length>30?'\n… ещё '+(record.items.length-30)+' позиций':'');
 const text=('📥 Бесплатная заявка №'+(record.number||record.id)+'\nНик в заявке: '+(record.nick||record.user)+'\nСпособ: '+(record.type==='stars'?'Stars':record.type==='gears'?'Гиры':'Брейнроты')+'\n\n'+what+'\n\nБаза: '+record.base+' токенов\nБонус: '+record.bonus+'%\nК начислению: '+record.total+' токенов\n\nОжидание: 10 минут. Подтверждение — в админке BrainUp.\nПередача предметов и оплата не требуются.').slice(0,4096);
 const response=await fetch('https://api.telegram.org/bot'+env.TELEGRAM_BOT_TOKEN+'/sendMessage',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({chat_id:1116312381,text}),signal:AbortSignal.timeout(7000)}),result=await response.json();
 if(!response.ok||!result.ok)throw Error('Telegram free-request notification failed');return result.result;
}

export async function checkBonusSubscription(env,userId){
 if(!env.TELEGRAM_BOT_TOKEN)throw Error('Bot not configured');
 const channel=env.TELEGRAM_NEWS_CHANNEL||'@BrainUp_Official';
 const response=await fetch('https://api.telegram.org/bot'+env.TELEGRAM_BOT_TOKEN+'/getChatMember',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({chat_id:channel,user_id:userId}),signal:AbortSignal.timeout(8000)});
 const data=await response.json();if(!response.ok||!data.ok){const description=String(data.description||'');if(/member list|administrator|not enough rights|CHAT_ADMIN_REQUIRED/i.test(description))throw Error('Боту нужны права администратора канала '+channel);if(/chat not found|CHANNEL_INVALID/i.test(description))throw Error('Канал '+channel+' недоступен боту. Проверьте канал и добавьте в него бота');throw Error('Telegram не ответил на проверку подписки. Повторите попытку');}
 return ['creator','administrator','member'].includes(data.result.status)||(data.result.status==='restricted'&&data.result.is_member===true);
}

