export function dropPlayerId(state,drop){
 if(drop?.userId&&state.users[drop.userId])return drop.userId;
 if(!drop?.user)return null;
 const matches=Object.values(state.users).filter(user=>user.me===drop.user);
 return matches.length===1?matches[0].id:null;
}
export function publicPlayerProfile(state,seed,query={}){
 let id=String(query.userId||'');
 if(!id&&query.dropId){const drop=(state.drops||[]).find(drop=>drop.id===query.dropId)||(state.topDrop?.id===query.dropId?state.topDrop:null);id=dropPlayerId(state,drop)||''}
 const user=state.users[id];
 if(!user||user.banned)throw Error('Профиль игрока недоступен');
 const catalog=new Map([...seed.items,...(state.config.custom||[])].map(item=>[item.id,withCatalogPrice(item,state.config.itemPrices)])),grouped=new Map();
 let totalValue=0;
 for(const entry of user.inv){const item=catalog.get(entry.id);if(!item)continue;totalValue+=item.price;const group=grouped.get(item.id)||{id:item.id,name:item.name,price:item.price,qty:0};group.qty++;grouped.set(item.id,group)}
 const inventory=[...grouped.values()].sort((a,b)=>b.price-a.price||a.name.localeCompare(b.name));
 const pages=Math.max(1,Math.ceil(inventory.length/48)),page=Math.max(1,Math.min(pages,Math.floor(Number(query.page)||1)));
 return {id:user.id,name:user.me,stats:{inventoryCount:user.inv.length,inventoryValue:Math.round(totalValue*100)/100,wins:user.win||0,losses:user.lose||0,upgrades:user.upg||0},items:inventory.slice((page-1)*48,page*48),page,pages};
}

export function telegramReferralUrl(username,code){
 if(!/^[A-Za-z0-9_]{5,32}$/.test(username||'')||!/^[A-Z0-9_-]{3,20}$/.test(code||''))throw Error('Реферальная ссылка недоступна');
 return 'https://t.me/'+username+'?start=ref_'+code;
}

const DEFAULT_CASE_SECTIONS=[
 {id:'free',name:'Бесплатные кейсы'},
 {id:'theme',name:'Тематические кейсы'},
 {id:'all-in',name:'All-In'},
 {id:'partners',name:'Партнеры'},
 {id:'basic',name:'Базовые кейсы'},
 {id:'other',name:'Другие кейсы'}
];
function caseSectionList(config={}){
 const raw=Array.isArray(config.caseSections)?config.caseSections:DEFAULT_CASE_SECTIONS,seen=new Set();
 const list=raw.filter(section=>section&&typeof section.id==='string'&&typeof section.name==='string'&&section.name.trim()&&!seen.has(section.id)&&seen.add(section.id)).map(section=>({id:section.id,name:section.name}));
 if(!list.some(section=>section.id==='other'))list.push({id:'other',name:'Другие кейсы'});
 return list;
}
function caseSectionFor(c,sections){
 if(c.sectionId&&sections.some(section=>section.id===c.sectionId))return c.sectionId;
 if(c.bonus&&sections.some(section=>section.id==='free'))return 'free';
 if(c.grp&&sections.some(section=>section.id===c.grp))return c.grp;
 return 'other';
}

const CASE_ITEM_EXPONENT=2.1;
const FREE_CASE_ODDS={coins2:.72,coins5:.19,coins:.91,items:.09};
const SPECIAL_CASE_ODDS={dragon:.36,noobini:.64};
// One set of weights supplies both the displayed pool and server draws.
function isFiftyFiftyCase(c) {
 if(!c||c.bonus)return false;
 const name=String(c.name||'').normalize('NFKC').toLocaleLowerCase('ru').replace(/кейс|case/g,'').replace(/[^a-zа-яё0-9]/g,'');
 return /^50(?:на|x|х)?50$/.test(name);
}
function caseItemWeight(c,item){
 if(isFiftyFiftyCase(c))return Number(item.id)===55?SPECIAL_CASE_ODDS.dragon:Number(item.id)===95?SPECIAL_CASE_ODDS.noobini:0;
 return Math.pow(item.price,-CASE_ITEM_EXPONENT);
}
function pickCaseItem(c,items,rng=Math.random){
 if(isFiftyFiftyCase(c)){const selectedId=rng()<SPECIAL_CASE_ODDS.dragon?55:95;return items.find(item=>Number(item.id)===selectedId)}
 let roll=rng()*items.reduce((sum,item)=>sum+caseItemWeight(c,item),0);
 for(const item of items){roll-=caseItemWeight(c,item);if(roll<0)return item}
 return items.at(-1);
}
function activationCaseRewardPool(items){
 const sum=items.reduce((total,item)=>total+Math.pow(item.price,-CASE_ITEM_EXPONENT),0);
 return [{id:'token-2',name:'2 монеты',price:2,rewardKind:'coins',rewardWeight:FREE_CASE_ODDS.coins2},{id:'token-5',name:'5 монет',price:5,rewardKind:'coins',rewardWeight:FREE_CASE_ODDS.coins5}].concat(items.map(item=>Object.assign({},item,{rewardWeight:FREE_CASE_ODDS.items*Math.pow(item.price,-CASE_ITEM_EXPONENT)/sum})));
}

// Percentages supplied by the site owner. Each percentage uses the item's base credit.
